mapper.select:
SELECT id, user_id, agent_code, session_id, summary_text,
       covered_run_db_id, covered_run_id, summarized_turn_count,
       summary_version, status, last_error_code, created_time, updated_time
FROM agent_session_summary
WHERE user_id = #{userId}
  AND agent_code = #{agentCode}
  AND session_id = #{sessionId}
LIMIT 1

mapper.update:
UPDATE agent_session_summary
SET summary_text = #{summaryText},
    covered_run_db_id = #{coveredRunDbId},
    covered_run_id = #{coveredRunId},
    summarized_turn_count = #{summarizedTurnCount},
    summary_version = summary_version + 1,
    status = 'ACTIVE',
    last_error_code = NULL,
    updated_time = CURRENT_TIMESTAMP(3)
WHERE user_id = #{userId}
  AND agent_code = #{agentCode}
  AND session_id = #{sessionId}
  AND summary_version = #{expectedVersion}

UPDATE agent_session_summary
SET status = 'FAILED',
    last_error_code = #{errorCode},
    updated_time = CURRENT_TIMESTAMP(3)
WHERE user_id = #{userId}
  AND agent_code = #{agentCode}
  AND session_id = #{sessionId}
  AND summary_version = #{expectedVersion}
